//! 📨️ Copies an already selected visible row under independent physical grants.
use crate::MutationMessage;
use crate::MutationMessageRetirement;
use semio_framework_value::{ErasedSnapshotRetirement, ValueError, ValueRefusalKind, retained_clone::{RetainedCloneGrant, RetainedCloneProgress, RetainedCloneStep}};
use std::mem::{ManuallyDrop,size_of};
pub struct MessageCopyCursor { source:Option<usize>, output:ManuallyDrop<Option<MutationMessage>>, active:Option<MutationMessageRetirement>, segment:usize, phase:u8, allocated:bool, cancelled:bool, closing:bool }
fn refusal()->ValueError {ValueError::literal(ValueRefusalKind::InvariantViolated,"selected message copy lost immutable admitted owner")}
impl Default for MessageCopyCursor {fn default()->Self{Self::new()}}
impl MessageCopyCursor {
 pub fn new()->Self{Self {source:None,output:ManuallyDrop::new(None),active:None,segment:0,phase:0,allocated:false,cancelled:false,closing:false}}
 fn source(&self,source:&MutationMessage)->Result<(),ValueError>{if self.source.is_some_and(|expected|expected!=std::ptr::from_ref(source)as usize){Err(refusal())}else{Ok(())}}
 pub fn next_capacity_byte_demand(&self,source:&MutationMessage)->Result<usize,ValueError>{self.source(source)?;if self.phase==0{return source.target.len().checked_mul(size_of::<String>()).ok_or_else(refusal);}if self.allocated||self.phase==4{return Ok(0);}Ok(match self.phase{1=>source.code.0.len(),2=>source.message.len(),3 if self.segment<source.target.len()&&self.output.as_ref().is_some_and(|output|output.target.len()>self.segment)=>source.target[self.segment].len(),_=>0})}
 pub fn next_copy_byte_demand(&self,source:&MutationMessage)->Result<usize,ValueError>{self.source(source)?;if !self.allocated||self.phase==0||self.phase==4{return Ok(if self.phase==3&&self.segment<source.target.len()&&self.output.as_ref().is_some_and(|output|output.target.len()==self.segment){size_of::<String>()}else{0});}let output=self.output.as_ref().ok_or_else(refusal)?;let(input,length)=match self.phase{1=>(source.code.0.as_str(),output.code.0.len()),2=>(source.message.as_str(),output.message.len()),3 if self.segment<source.target.len()=>(source.target[self.segment].as_str(),output.target[self.segment].len()),_=>return Ok(0)};Ok(input.get(length..).ok_or_else(refusal)?.chars().next().map_or(0,char::len_utf8))}
 pub fn advance(&mut self,source:&MutationMessage,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.source(source)?;let idle=RetainedCloneProgress::default();if self.cancelled||self.closing||grant.maximum_items==0||grant.maximum_depth==0{return Ok(RetainedCloneStep::Progress(idle));}if self.phase==4{return Ok(RetainedCloneStep::Complete(idle));}let capacity=self.next_capacity_byte_demand(source)?;let copied=self.next_copy_byte_demand(source)?;if capacity>crate::MUTATION_MESSAGE_ENTRY_BYTES{return Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"message copy requires final bounded row selection"));}if capacity>grant.maximum_capacity_bytes||copied>grant.maximum_copy_bytes{return Ok(RetainedCloneStep::Progress(idle));}self.source=Some(std::ptr::from_ref(source)as usize);let mut progress=RetainedCloneProgress {copied_items:1,..idle};if self.phase==0{let mut targets=Vec::new();targets.try_reserve_exact(source.target.len()).map_err(|_|refusal())?;progress.retained_capacity_bytes=targets.capacity()*size_of::<String>();*self.output=Some(MutationMessage {level:source.level,code:String::new().into(),message:String::new(),target:targets,op_index:source.op_index});self.phase=1;return Ok(RetainedCloneStep::Progress(progress));}let output=self.output.as_mut().ok_or_else(refusal)?;if self.phase==3&&self.segment==source.target.len(){self.phase=4;return Ok(RetainedCloneStep::Complete(progress));}if self.phase==3&&output.target.len()==self.segment{output.target.push(String::new());progress.copied_bytes=size_of::<String>();return Ok(RetainedCloneStep::Progress(progress));}let(input,destination)=match self.phase{1=>(source.code.0.as_str(),&mut output.code.0),2=>(source.message.as_str(),&mut output.message),3=>(source.target[self.segment].as_str(),&mut output.target[self.segment]),_=>return Err(refusal())};if !self.allocated{destination.try_reserve_exact(input.len()).map_err(|_|refusal())?;progress.retained_capacity_bytes=destination.capacity();self.allocated=true;}else if let Some(scalar)=input.get(destination.len()..).ok_or_else(refusal)?.chars().next(){destination.push(scalar);progress.copied_bytes=scalar.len_utf8();}else{self.allocated=false;if self.phase<3{self.phase+=1;}else{self.segment+=1;}}Ok(RetainedCloneStep::Progress(progress))}
 pub fn take(&mut self)->Option<MutationMessage>{if self.phase==4&&!self.cancelled&&!self.closing{self.output.take()}else{None}}
 pub fn cancel(&mut self){self.cancelled=true;}
 pub fn begin_close(&mut self){self.closing=true;}
 pub fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.active.as_ref().map_or(usize::from(self.output.is_some())*size_of::<MutationMessage>(),MutationMessageRetirement::next_copy_byte_demand))}
 pub fn next_close_capacity_byte_demand(&self,_:usize)->Result<usize,ValueError>{Ok(0)}
 pub fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.active.as_ref().map_or(0,MutationMessageRetirement::next_release_byte_demand))}
 pub fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(if self.active.is_some(){2}else{usize::from(!self.terminal_is_empty())})}
 pub fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let idle=RetainedCloneProgress::default();if !self.closing||grant.maximum_items==0||grant.maximum_depth<self.next_close_depth_demand()?||grant.maximum_copy_bytes<self.next_close_copy_byte_demand()?||grant.maximum_release_bytes<self.next_close_release_byte_demand()?{return Ok(RetainedCloneStep::Progress(idle));}if let Some(active)=self.active.as_mut(){let progress=active.close_step(grant);if active.terminal_is_empty(){self.active=None;}return Ok(RetainedCloneStep::Progress(progress));}if let Some(output)=self.output.take(){self.active=Some(MutationMessageRetirement::new(output));return Ok(RetainedCloneStep::Progress(RetainedCloneProgress {copied_items:1,copied_bytes:size_of::<MutationMessage>(),..idle}));}self.source=None;Ok(RetainedCloneStep::Complete(idle))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.source.is_none()&&self.output.is_none()&&self.active.is_none()}
 pub fn into_retirement(mut self)->Self{self.cancel();self.begin_close();self}
 pub fn close_cold(&mut self){self.cancel();self.begin_close();while !self.terminal_is_empty(){self.close_step(RetainedCloneGrant {maximum_items:1,maximum_copy_bytes:usize::MAX,maximum_capacity_bytes:usize::MAX,maximum_release_bytes:usize::MAX,maximum_depth:usize::MAX}).expect("cold selected row closure");}}
}
impl ErasedSnapshotRetirement for MessageCopyCursor {
 fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{Self::close_step(self,grant)}
 fn terminal_is_empty(&self)->bool{Self::terminal_is_empty(self)}
 fn next_copy_byte_demand(&self)->Result<usize,ValueError>{self.next_close_copy_byte_demand()}
 fn next_capacity_byte_demand(&self,body:usize)->Result<usize,ValueError>{self.next_close_capacity_byte_demand(body)}
 fn next_release_byte_demand(&self)->Result<usize,ValueError>{self.next_close_release_byte_demand()}
 fn next_depth_demand(&self)->Result<usize,ValueError>{self.next_close_depth_demand()}
}
impl Drop for MessageCopyCursor {fn drop(&mut self){let empty=self.terminal_is_empty();assert!(empty||std::thread::panicking(),"selected message copy must reach physical terminal ownership");if empty{unsafe{ManuallyDrop::drop(&mut self.output);}}}}
